import { test, expect } from '@playwright/test';

test.describe('File Upload - Set Title and Description', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should successfully set title and description for an uploaded file', async ({ page }) => {
    // Intercept the file upload API
    await page.route('**/api/files/upload', (route) => {
      route.continue();
    });

    // Upload a file using getByLabel
    const fileInput = page.getByLabel('Upload File');
    await fileInput.setInputFiles('fixtures/sample-file.pdf');

    // Verify file is listed
    const fileList = page.getByRole('listbox', { name: /files/i });
    await expect(fileList).toBeVisible();

    // Set title using getByLabel
    const titleInput = page.getByLabel('File Title');
    await expect(titleInput).toBeVisible();
    await titleInput.fill('Sample PDF Document');

    // Set description using getByLabel
    const descriptionInput = page.getByLabel('File Description');
    await expect(descriptionInput).toBeVisible();
    await descriptionInput.fill('This is a sample PDF document for testing file upload functionality.');

    // Submit the form
    const submitButton = page.getByRole('button', { name: /upload/i });
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('File uploaded successfully');
    await expect(successMessage).toBeVisible();

    // Verify title and description are set in the file details
    const fileDetails = page.getByText('Sample PDF Document');
    await expect(fileDetails).toBeVisible();

    const fileDescription = page.getByText('This is a sample PDF document for testing file upload functionality.');
    await expect(fileDescription).toBeVisible();

    // Verify file is listed with title and description
    const fileItem = page.getByText('Sample PDF Document');
    await expect(fileItem).toBeVisible();
  });

  test('should handle empty title and description input', async ({ page }) => {
    // Upload a file using getByLabel
    const fileInput = page.getByLabel('Upload File');
    await fileInput.setInputFiles('fixtures/sample-file.pdf');

    // Verify file is listed
    const fileList = page.getByRole('listbox', { name: /files/i });
    await expect(fileList).toBeVisible();

    // Set title using getByLabel
    const titleInput = page.getByLabel('File Title');
    await expect(titleInput).toBeVisible();
    await titleInput.fill('');

    // Set description using getByLabel
    const descriptionInput = page.getByLabel('File Description');
    await expect(descriptionInput).toBeVisible();
    await descriptionInput.fill('');

    // Submit the form
    const submitButton = page.getByRole('button', { name: /upload/i });
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('File uploaded successfully');
    await expect(successMessage).toBeVisible();

    // Verify file is listed without title and description
    const fileItem = page.getByText('Sample PDF Document');
    await expect(fileItem).toBeVisible();

    // Verify no title or description is displayed
    const titleDisplay = page.getByText('Sample PDF Document');
    await expect(titleDisplay).not.toBeVisible();

    const descriptionDisplay = page.getByText('This is a sample PDF document for testing file upload functionality.');
    await expect(descriptionDisplay).not.toBeVisible();
  });
});
